.tabs button,header button{white-space:nowrap}header select{min-width:0}@media(max-width:700px){h1{display:none}header{gap:6px}.tabs{margin-left:0}.tabs button{padding:6px 8px}header select{max-width:96px}}
#main>#p_cfg.on{display:grid;align-content:start;grid-template-columns:168px minmax(0,1fr);gap:var(--gap);align-items:start;flex:1 1 auto}
#cfgnav{display:flex;flex-direction:column;gap:2px;position:sticky;top:0}
#cfgnav button{background:transparent;color:var(--mu);text-align:left;padding:8px 12px;border-radius:8px;font-weight:600;border:0;box-shadow:inset 3px 0 0 transparent}
#cfgnav button.on{background:var(--card2);color:var(--fg);box-shadow:inset 3px 0 0 var(--ac)}
#cfgbody>.card{display:none}#cfgbody>.card.on{display:block}#cfgbody .card h2{font-size:1rem;margin-bottom:10px}
#cfgbody .mu{margin:6px 0 10px}#cfgbody .row{align-items:flex-end}#cfgbody .fld{min-width:150px}
@media(max-width:700px){#main>#p_cfg.on{grid-template-columns:1fr}#cfgnav{flex-direction:row;overflow-x:auto;position:static;gap:4px}#cfgnav button{white-space:nowrap;box-shadow:inset 0 -3px 0 transparent}#cfgnav button.on{box-shadow:inset 0 -3px 0 var(--ac)}}
header #logo{display:none;width:36px;height:36px;border-radius:0;box-shadow:none;padding:0;background:none;filter:drop-shadow(0 0 8px var(--ac))}header #brand{display:block;width:auto;height:clamp(38px,5.4vw,58px);border-radius:0;box-shadow:none;padding:0;background:none;filter:drop-shadow(0 0 7px rgba(124,58,237,.55))}@media(max-width:760px){header #brand{display:none}header #logo{display:block}}
#main>#p_q.on{display:block}#qcol{display:grid;gap:var(--gap);grid-template-columns:1fr}@media(min-width:900px){#qcol{grid-template-columns:1fr 1fr;align-items:start}}
#qcard h2,#hcard h2{display:flex;align-items:center;gap:8px}.grow{flex:1}.lst{display:flex;flex-direction:column;gap:6px;max-height:52vh;overflow:auto}.lst .emp{color:var(--mu);padding:14px 4px}
.qi{display:flex;align-items:center;gap:10px;padding:8px 10px;border:1px solid var(--line);border-radius:var(--r);background:var(--card2)}.qi .qs{flex:none;font-size:.72rem;font-weight:700;padding:2px 8px;border-radius:99px;background:var(--line);color:var(--fg)}
.qi.st-running .qs{background:var(--ac);color:var(--acfg)}.qi.st-done .qs{background:var(--ok);color:#06210f}.qi.st-failed .qs,.qi.st-stopped .qs{background:var(--bad);color:#2a0710}
.qt{min-width:0;flex:1;display:flex;flex-direction:column}.qt b{white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.qt small{color:var(--mu)}.qa{display:flex;gap:4px;flex:none}.qa button{padding:3px 9px}
.qn{font-style:normal;margin-left:6px;font-size:.72rem;font-weight:800;background:var(--ac);color:var(--acfg);padding:1px 7px;border-radius:99px}.qn:empty{display:none}
#rs{position:fixed;left:50%;top:10px;transform:translateX(-50%);z-index:9999;display:flex;gap:10px;align-items:center;flex-wrap:wrap;justify-content:center;max-width:92vw;padding:10px 16px;background:var(--card);border:1px solid var(--ac);border-radius:var(--r);box-shadow:var(--sh)}#rs[hidden]{display:none}
#cd{position:fixed;left:50%;top:10px;transform:translateX(-50%);z-index:9999;display:flex;gap:12px;align-items:center;padding:10px 16px;background:var(--card);border:1px solid var(--ac);border-radius:var(--r);box-shadow:var(--sh)}#cd[hidden]{display:none}
#main>#p_lib.on{display:block}#lib{display:grid;gap:var(--gap);grid-template-columns:minmax(0,1fr);margin-top:10px}#lib>*{min-width:0}@media(min-width:980px){#lib{grid-template-columns:minmax(380px,5fr) minmax(0,6fr);align-items:start}#lstage{position:sticky;top:8px}}
#lstage{padding:14px}#lscreen{position:relative;aspect-ratio:16/9;border-radius:var(--r);overflow:hidden;background:radial-gradient(120% 120% at 20% 10%,color-mix(in srgb,var(--ac) 38%,#000),#07080d 70%);display:flex;align-items:center;justify-content:center}
#lscreen video{position:absolute;inset:0;width:100%;height:100%;background:#000;object-fit:contain;display:none;cursor:pointer}#lstage.vid #lscreen video{display:block}#lstage.vid #lart{display:none}
#lart{display:flex;flex-direction:column;align-items:center;gap:14px;height:100%;justify-content:center}
.disc{height:56%;aspect-ratio:1;border-radius:50%;background:conic-gradient(from 0deg,var(--ac),#111 18%,var(--ac) 36%,#111 54%,var(--ac) 72%,#111 90%,var(--ac));box-shadow:0 8px 28px rgba(0,0,0,.55),inset 0 0 0 5px rgba(255,255,255,.08);display:flex;align-items:center;justify-content:center;animation:lspin 6s linear infinite;animation-play-state:paused}
.disc i{width:30%;aspect-ratio:1;border-radius:50%;background:#0b0d14;box-shadow:0 0 0 4px rgba(255,255,255,.14)}#lstage.playing .disc{animation-play-state:running}@keyframes lspin{to{transform:rotate(360deg)}}
.eq{display:flex;gap:4px;align-items:flex-end;height:20px}.eq b{width:5px;height:4px;border-radius:2px;background:var(--ac);opacity:.9}#lstage.playing .eq b{animation:leq .9s ease-in-out infinite}.eq b:nth-child(2){animation-delay:.12s!important}.eq b:nth-child(3){animation-delay:.3s!important}.eq b:nth-child(4){animation-delay:.05s!important}.eq b:nth-child(5){animation-delay:.22s!important}.eq b:nth-child(6){animation-delay:.38s!important}.eq b:nth-child(7){animation-delay:.17s!important}@keyframes leq{0%,100%{height:4px}50%{height:20px}}
#linfo{display:flex;flex-direction:column;margin:12px 2px 6px;min-width:0}#lnow{font-size:1.08rem;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}#lsub{color:var(--mu);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
#lseekrow{display:flex;align-items:center;gap:10px}#lseekrow span{font-size:.74rem;color:var(--mu);min-width:38px;font-variant-numeric:tabular-nums}#lseekrow span:last-child{text-align:right}
#lstage input[type=range]{-webkit-appearance:none;appearance:none;height:6px;border-radius:99px;background:linear-gradient(to right,var(--ac) var(--p,0%),var(--line) var(--p,0%));padding:0;border:0;outline:none;cursor:pointer;min-width:0}
#lstage input[type=range]::-webkit-slider-thumb{-webkit-appearance:none;width:14px;height:14px;border-radius:50%;background:var(--ac);border:2px solid var(--card);box-shadow:0 0 0 1px var(--ac)}#lstage input[type=range]:focus-visible{box-shadow:0 0 0 3px color-mix(in srgb,var(--ac) 40%,transparent)}#lseek{flex:1}
#lctl{display:flex;align-items:center;justify-content:center;gap:10px;margin:10px 0 6px}
#lstage .ib{background:var(--card2);color:var(--fg);border:1px solid var(--line);border-radius:50%;width:42px;height:42px;padding:0;font-size:1.05rem;display:inline-flex;align-items:center;justify-content:center;flex:none;min-width:0;cursor:pointer}#lstage .ib:hover{border-color:var(--ac)}
#lstage .ib.big{width:58px;height:58px;font-size:1.4rem;background:var(--ac);color:var(--acfg);border-color:var(--ac);box-shadow:0 4px 16px color-mix(in srgb,var(--ac) 45%,transparent)}#lstage .ib.sm{width:34px;height:34px;font-size:.95rem;border-radius:var(--r)}#lstage .ib.on{background:var(--ac);color:var(--acfg);border-color:var(--ac)}
#lsec{display:flex;align-items:center;gap:8px;flex-wrap:nowrap}#lvol{width:96px;flex:none}#lspd{width:auto;min-width:0;flex:none;padding:5px 6px}#lerr{min-height:1.2em;margin-top:4px;font-size:.82rem}
#lbar{display:flex;gap:8px;flex-wrap:wrap;align-items:center;margin:8px 0}#lbar #lq{flex:1;min-width:140px}#lbar select{width:auto;flex:none}.lseg{display:inline-flex;gap:4px}.lseg button.on{background:var(--ac);color:var(--acfg)}
#llist{max-height:56vh;min-height:120px}.li{display:flex;align-items:center;gap:10px;padding:7px 10px;border:1px solid var(--line);border-radius:var(--r);background:var(--card2);cursor:pointer}.li:hover{border-color:var(--ac)}
.li.on{border-color:var(--ac);background:color-mix(in srgb,var(--ac) 16%,var(--card2))}.li .ic{flex:none;width:34px;height:34px;border-radius:8px;background:var(--line);display:flex;align-items:center;justify-content:center;font-size:.95rem}.li.on .ic{background:var(--ac);color:var(--acfg)}
.li .lt{min-width:0;flex:1;display:flex;flex-direction:column}.li .lt b{white-space:nowrap;overflow:hidden;text-overflow:ellipsis;font-weight:600}.li .lt small{color:var(--mu);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.li .lo{flex:none;border:0;background:transparent;color:var(--mu);font-size:1rem;padding:4px 7px;border-radius:6px;cursor:pointer}.li .lo:hover{background:var(--line);color:var(--fg)}
#lfold{margin-top:10px}#lfold summary{cursor:pointer;font-weight:600;padding:6px 0}.lfr{display:flex;align-items:center;gap:8px;padding:5px 8px;border:1px solid var(--line);border-radius:var(--r);margin:6px 0;background:var(--card2)}.lfr span{flex:1;min-width:0;overflow-wrap:anywhere;font-size:.86rem}.lfr em{font-style:normal;color:var(--mu);font-size:.74rem}.lfr button{flex:none;padding:3px 9px}
.lfadd{display:flex;gap:8px;flex-wrap:wrap;margin-top:8px}.lfadd input{flex:1;min-width:150px}#lfmsg{min-height:1.2em;margin-top:4px;font-size:.82rem}
@media(max-width:520px){#lvol{width:70px}#lstage{padding:10px}#lctl{gap:6px}#lstage .ib{width:38px;height:38px}#lstage .ib.big{width:54px;height:54px}}
@media(prefers-reduced-motion:reduce){.disc,#lstage.playing .disc,#lstage.playing .eq b{animation:none!important}}
/* telas estreitas: com 5 abas o cabecalho estourava a largura; as abas vao para uma linha propria */
@media(max-width:560px){header{flex-wrap:wrap}header .tabs{order:3;flex:1 0 100%;margin:4px 0 0;overflow-x:auto}header .tabs button{flex:1 0 auto}header #logo{flex:none}header label.fld{margin-left:auto}}

/* tela cheia: o cartao inteiro (video/capa + controles), nao so o quadro do video */
#lstage:fullscreen{background:#000;display:flex;flex-direction:column;padding:18px 28px;border-radius:0;border:0;position:static}#lstage:fullscreen #lscreen{aspect-ratio:auto;flex:1;min-height:0;border-radius:0}#lstage:fullscreen #linfo{margin-top:12px}#lstage:fullscreen #lctl{margin:12px 0 6px}
/* Seletor de faixas: o cartao "escolha o que quer" nao pode ser empurrado para o fim da pagina
