const LOGO='data:image/png;base64,';$('logo').src=LOGO;$('brand').src='data:image/webp;base64,';$('fav').href=LOGO;
let LANG='en';
const t=k=>(D[LANG]&&D[LANG][k])||D.en[k]||k;
const api=(p,b)=>fetch('/api/'+p+(p.indexOf('?')<0?'?':'&')+'t='+T,b?{method:'POST',headers:{'X-KoeDL':'1','Content-Type':'application/json'},body:JSON.stringify(b)}:{headers:{'X-KoeDL':'1'}}).then(r=>r.json());
const esc=s=>String(s==null?'':s).replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
let cur='links',P={items:[],from:0,busy:false,title:'',url:''},ready=false,running=false,lastStatus=null;
const IDS=['rate','frag','dirAudio','dirVideo','notif','after','autoclip','lookv','selfUpd','lang','openMode','theme','accent','fsize','density','corner','afmt','aq','vq','vcont','plmode','num','batch','splitType','st','en','noPl','nock','wait','meta','safe','reset','alt','addId','dlDir','chan','curmode','curpx2','curanim'];
const FS={s:12,m:14,l:16,xl:18};
function scl(){return Math.max(.85,Math.min(1.6,Math.min(innerWidth/1060,innerHeight/720)))}
window.addEventListener('resize',function(){try{applyLook()}catch(e){}});
function applyLook(){const h=document.documentElement,th=$('theme').value;
if(th==='auto')h.removeAttribute('data-theme');else h.setAttribute('data-theme',th);
h.style.fontSize=((FS[$('fsize').value]||14)*scl())+'px';
if($('density').value==='compact')h.setAttribute('data-dens','compact');else h.removeAttribute('data-dens');
applyCursor();if($('corner').value==='square')h.setAttribute('data-corner','square');else h.removeAttribute('data-corner');
const c=$('accent').value||'#7c3aed';h.style.setProperty('--ac',c);
const n=parseInt(c.slice(1),16),r=n>>16,g=(n>>8)&255,b=n&255,L=(0.299*r+0.587*g+0.114*b);h.style.setProperty('--acfg',L>150?'#111':'#fff');
document.querySelectorAll('#sw button[data-c]').forEach(x=>{x.style.background=x.dataset.c;x.classList.toggle('on',x.dataset.c.toLowerCase()===c.toLowerCase())})}
function resetLook(){$('theme').value='neon';$('fsize').value='m';$('density').value='compact';$('corner').value='round';$('curmode').value='pack';$('curpx2').value='32';$('curanim').value='full';$('accent').value='#7c3aed';applyLook();save()}
document.querySelectorAll('#sw button[data-c]').forEach(x=>x.addEventListener('click',()=>{$('accent').value=x.dataset.c;applyLook();save()}));
function radio(n){const e=document.querySelector('input[name='+n+']:checked');return e?e.value:''}
function setRadio(n,v){document.querySelectorAll('input[name='+n+']').forEach(e=>e.checked=e.value===v)}
function updFmt(){const k=radio('kind'),pm=radio('pm');
const a=k==='a'||pm!=='v',v=k==='v'||pm!=='a';
$('gA').classList.toggle('hide',!a);$('gV').classList.toggle('hide',!v);
}

function cfgNav(){var nav=$('cfgnav'),cards=[].slice.call(document.querySelectorAll('#cfgbody>.card'));nav.innerHTML='';
 cards.forEach(function(c,i){var key=c.querySelector('h2').dataset.t,b=document.createElement('button');if(key==='h_where')key='n_where';if(key==='h_acc')key='n_acc';b.dataset.t=key;b.textContent=t(key);
  b.onclick=function(){cards.forEach(function(x,j){x.classList.toggle('on',j===i)});[].forEach.call(nav.children,function(x,j){x.classList.toggle('on',j===i)});try{sessionStorage.setItem('cfgsec',i)}catch(e){}};nav.appendChild(b)});
 var k=0;try{k=+sessionStorage.getItem('cfgsec')||0}catch(e){} if(k>=cards.length)k=0;nav.children[k].click()}
function applyLang(){document.documentElement.lang=LANG;
document.querySelectorAll('[data-t]').forEach(e=>e.textContent=t(e.dataset.t));
document.querySelectorAll('[data-ph]').forEach(e=>e.placeholder=t(e.dataset.ph));
$('go').textContent=t('go');updGop();
if(P.items.length){render()}else if(!P.busy){$('plinfo').textContent=t('plhint')}
if(lastStatus)showStatus(lastStatus)}
function tab(k){cur=k;document.body.dataset.tab=k;for(const x of['links','q','lib','cfg','sup']){$('p_'+x).classList.toggle('on',x===k);$('t_'+x).classList.toggle('on',x===k)}
if(k==='lib')libLoad();updFmt()}
function common(){const o={};for(const i of IDS){const e=$(i);o[i]=e.type==='checkbox'?e.checked:e.value}
o.browsers=[...document.querySelectorAll('.br:checked')].map(e=>e.value);o.kind=radio('kind');o.pm=radio('pm');o.plurl=$('plurl').value;return o}
let sv=null;function save(){clearTimeout(sv);sv=setTimeout(()=>api('settings',common()),400)}
async function load(){try{const s=await api('settings');for(const i of IDS){if(!(i in s))continue;const e=$(i);if(e.type==='checkbox')e.checked=!!s[i];else e.value=s[i]}
if(s.browsers)document.querySelectorAll('.br').forEach(e=>e.checked=s.browsers.indexOf(e.value)>=0);if(s.kind)setRadio('kind',s.kind);if(s.pm)setRadio('pm',s.pm);if(s.plurl)$('plurl').value=s.plurl}catch(e){}
if($('lookv').value!=='3'){$('theme').value='neon';$('density').value='compact';$('curanim').value='full';$('accent').value='#7c3aed';$('lookv').value='3';save()}
LANG=$('lang').value||'en';if(!D[LANG])LANG='en';$('lang').value=LANG;applyLook();cfgNav();applyLang();updFmt();
document.querySelectorAll('input,select').forEach(e=>{e.addEventListener('change',save);if(e.type==='color')e.addEventListener('input',()=>{applyLook();save()})});
['theme','fsize','density','corner','curmode','curpx2','curanim'].forEach(i=>$(i).addEventListener('change',applyLook));
$('lang').addEventListener('change',()=>{LANG=$('lang').value;applyLang();save()});
document.querySelectorAll('input[name=kind]').forEach(e=>e.addEventListener('change',updFmt))}
function opts(){const o=common();o.urls=$('urls').value.split('\n').map(s=>s.trim()).filter(s=>s&&s[0]!=='#');return o}
function updGop(){const n=P.items.filter(x=>x.checked&&!x.unavail).length;$('gop').textContent=t('go_pick')+(n?' ('+n+')':'');$('gop').classList.toggle('hide',!P.items.length)}
async function go(m){let o,label,kind='a';
 if(m==='pick'){const sel=P.items.filter(x=>x.checked&&!x.unavail);if(!sel.length)return alert(t('a_pick'));
  o=common();o.mode='pick';o.plurl=P.url||o.plurl||'';o.plTitle=P.title;if(!o.plTitle)o.plmode='none';o.maxIdx=Math.max.apply(null,P.items.map(x=>x.idx||0).concat([P.items.length]));
  o.items=sel.map(x=>({idx:x.idx,title:x.title,url:x.url,type:x.type}));label=(P.title||'Playlist')+' · '+sel.length;kind=sel.every(x=>x.type==='v')?'v':'a'}
 else{o=opts();o.mode='links';if(!o.urls.length){$('urls').focus();return alert(t('a_links'))}
  label=o.urls[0].replace(/^https?:\/\/(www\.)?/,'').slice(0,60)+(o.urls.length>1?' +'+(o.urls.length-1):'');kind=o.kind==='v'?'v':'a';$('urls').value=''}
 enqueue(o,label,kind)}
/* ---- fila, historico e extras ---- */
var Q=[],qid=0,qpaused=false,curJob=null,HIST=[],batchN=0,cdT=null;
function qe(x){return String(x==null?'':x).replace(/[&<>"]/g,function(c){return{'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]})}
function enqueue(o,label,kind){var d=new Date(),z=function(n){return String(n).padStart(2,'0')};o.stamp=d.getFullYear()+'-'+z(d.getMonth()+1)+'-'+z(d.getDate())+' '+z(d.getHours())+'-'+z(d.getMinutes());Q.push({id:++qid,o:o,label:label,kind:kind,state:'queued',miss:0});qpaused=false;renderQ();pump();var n=$('ck');if(n){n.textContent=t('q_added');setTimeout(function(){if(n.textContent===t('q_added'))n.textContent=''},2500)}}
async function pump(){if(curJob||qpaused||!ready||running)return;var j=Q.find(function(x){return x.state==='queued'});if(!j)return;
 curJob=j;j.state='starting';renderQ();var r;try{r=await api('start',j.o)}catch(e){r={error:String(e)}}
 if(r&&r.error){j.state='failed';j.err=r.error;curJob=null;renderQ();setTimeout(pump,300);return}
 j.state='running';j.seen=false;j.miss=0;renderQ()}
function qTick(s){if(curJob&&curJob.state==='running'){if(s.running)curJob.seen=true;
  if(!s.running&&(curJob.seen||++curJob.miss>4))finishJob(s);else renderQ(true)}
 else if(!curJob)pump()}
function finishJob(s){var j=curJob;curJob=null;var nf=s.nfiles||0,fl=(s.fails||[]).length;
 j.n=nf;j.fails=fl;j.files=s.files||[];j.state=j.stopped?'stopped':(nf===0&&fl>0?'failed':'done');batchN+=nf;
 api('history',{entry:{t:Date.now(),label:j.label,kind:j.kind,ok:j.state==='done',n:nf,fails:fl,files:j.files.slice(0,40)}}).then(loadHist);
 renderQ();
 if(!qpaused&&!Q.some(function(x){return x.state==='queued'})){if(!j.stopped)allDone();batchN=0}else setTimeout(pump,300)}
function allDone(){if($('notif').checked)api('notify',{title:'KoeDL',text:t('ntf_done').replace('{n}',batchN)});
 var a=$('after').value;if(a==='quit'||a==='off')cdStart(a)}
function cdStart(a){var n=30;cdCancel();$('cd').hidden=false;var tick=function(){$('cdt').textContent=t(a==='off'?'cd_o':'cd_q').replace('{n}',n)};tick();
 cdT=setInterval(function(){n--;if(n<=0){clearInterval(cdT);cdT=null;$('cd').hidden=true;if(a==='off')api('poweroff',{});else api('quit',{})}else tick()},1000)}
