              $fu=[IO.Path]::GetFullPath($d); if($fu.TrimEnd('\','/').Length -le 2){ $bad+=$d; continue }; $fu=$fu.TrimEnd('\','/')
              if(-not ($ok | Where-Object { $_ -ieq $fu })){ $ok+=$fu } }catch{ $bad+=$d } }
